-- hoiho_suffixes.sql
--
-- CAIDA Hoiho per-suffix geolocation rulesets, as a lookup table.
--
-- GENERATED, do not edit by hand. Source:
--   https://publicdata.caida.org/datasets/topology/ark/ipv4/itdk/2025-08/
--   midar-iff-snmp-tnt.geo-re.jsonl.bz2        212,714 bytes compressed
--                                            2,306,906 bytes, 871 lines
--
-- WHAT THIS IS FOR. The question was whether an ISP node database with ZIP
-- codes could substitute for landmarks. The useful part of ITDK turned out NOT
-- to be its node files but this 212 KB ruleset: 871 DNS suffixes for which
-- CAIDA has machine-learned the operator naming convention that encodes a
-- location, each with a precision score. Applied to the last_hop_hostname
-- values this project ALREADY holds, it decodes the carrier node location with
-- no new measurement at all.
--
-- The columns are the ruleset metadata, not the regexes. The regexes stay in
-- the jsonl and are applied by CAIDA hoiho-apply.pl, or by a reimplementation.
-- This table answers the prior question: how much of our own traceroute data
-- the ruleset can even speak to.
--
--   klass        CAIDA score class, 767 good and 104 promising
--   ppv          positive predictive value of the rules for that suffix
--   routers      routers CAIDA matched with it, a proxy for how much it sees
--   hint_types   what the location tokens ARE, and this is the column that
--                decides whether ZIP is reachable:
--                  iata      476 suffixes, airport code, CITY granularity
--                  place     323 suffixes, place name,  CITY granularity
--                  clli       89 suffixes, CLLI code,   BUILDING granularity
--                  locode     12 suffixes, UN/LOCODE,   CITY granularity
--                  facility    2 suffixes
--
-- CLLI is the only one of those that is finer than a city. A CLLI code names a
-- specific building: 4 characters of place, 2 of state, 2 of building. The
-- Session 3 observation in zip_granularity_findings.md that AT&T publishes
-- lightspeed.btrgla.sbcglobal.net for Baton Rouge LA is precisely a CLLI
-- place-and-state prefix, BTRG + LA, and sbcglobal.net appears below with
-- clli hints at ppv 0.965. The project measured by hand what CAIDA has
-- generalised to 89 suffixes.
--
-- Attribution: CAIDA ITDK. The .nodes.geo files additionally include MaxMind
-- GeoLite2 data; this ruleset file does not.

DROP TABLE IF EXISTS hoiho_suffixes;

CREATE TABLE hoiho_suffixes (
    domain      text PRIMARY KEY,
    klass       text,
    ppv         numeric,
    routers     integer,
    geohints    integer,
    hint_types  text
);

