CREATE INDEX ON hoiho_suffixes (hint_types);
ANALYZE hoiho_suffixes;

SELECT count(*) AS suffixes,
       count(*) FILTER (WHERE klass = 'good')          AS good,
       count(*) FILTER (WHERE hint_types LIKE '%clli%') AS with_clli_hints,
       sum(routers)                                     AS routers_covered
FROM hoiho_suffixes;
